pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint _unlockTime, uint _putAmount, uint _collectAmount) public {
        vm.assume(_putAmount >= 1 ether && _putAmount <= address(this).balance);
        vm.assume(_collectAmount <= _putAmount && _collectAmount >= 1 ether);
        vm.assume(_unlockTime <= block.timestamp); // ensure immediate unlock

        uint beforeBalance = address(c).balance;
        c.Put{value: _putAmount}(_unlockTime);
        uint afterPutBalance = address(c).balance;

        c.Collect(_collectAmount);
        uint afterCollectBalance = address(c).balance;

