pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockDelta, uint256 putAmount, uint256 collectAmount) public {
        // Bound inputs to prevent overflow
        putAmount = bound(putAmount, 0, 1e27);
        collectAmount = bound(collectAmount, 0, 1e27);
        unlockDelta = bound(unlockDelta, 0, 1000000);

        // Ensure the caller has enough ether
        vm.deal(address(this), putAmount + 1 ether);

        // Call Put with an unlock time in the future
        uint256 unlockTime = block.timestamp + unlockDelta;
        c.Put{value: putAmount}(unlockTime);

        // Warp to after unlock time
        vm.warp(unlockTime + 1);

        // Get balance before Collect
        (uint256 balBefore, ) = c.Acc(address(this));

        // Call Collect with the amount
        (bool success, bytes memory) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get balance after Collect
        (uint256 balAfter, ) = c.Acc(address(this));

        // General rule: after a successful Collect, the balance decreases by exactly the collected amount
        // Because the bug adds 1 extra wei on every Put, the balance after a Collect will be one less than expected if the bug is present
        assertTrue((balBefore >= c.MinSum() && balBefore >= collectAmount) ? (balAfter == balBefore - collectAmount) : true);
    }
}

